BEGIN;

DELETE FROM questions WHERE topic = 'Embryogenesis & Development' AND subtopic IN ('Cell Migration & Apoptosis', 'Cell-Cell Communication', 'Differentiation & Stem-Cell Potency', 'Regeneration & Senescence', 'Specification & Determination');

-- Q1 [Specification & Determination | easy | Skill 1 | ans A]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Embryogenesis & Development', $sub1$Specification & Determination$sub1$, $qt1$A developmental biologist tracks a single cell in an early vertebrate embryo and notes the exact moment the cell becomes locked onto one developmental pathway, after which transplanting it to a new region of the embryo no longer changes what it will become. This event of committing the cell to a single fate is best identified as:$qt1$, $op1$[{"label": "A", "text": "determination, the irreversible commitment of the cell to one developmental pathway, after which it can no longer give rise to any other cell type"}, {"label": "B", "text": "determination, a temporary bias toward one fate that the cell can reverse if signals from its surroundings later change"}, {"label": "C", "text": "determination, the visible change in the cell's size, shape, and protein content that marks its final specialized state"}, {"label": "D", "text": "determination, the unequal splitting of the egg cytoplasm among daughter cells during the first cleavage divisions"}]$op1$::jsonb, 'A', $ex1$This is a Biology question that falls under the content category 'Mechanisms of Development'. The answer is A because determination is defined as the cell becoming irreversibly committed to a single developmental pathway, so it can no longer become any other cell type. The texts describe cells "becoming irreversibly committed to a developmental pathway" (A&P) and note that undetermined embryonic cells retain "the ability to develop into any cell type until their fate is programmed at a later developmental stage" (Biology); once that fate is programmed (determined), that flexibility is lost. The hallmark of determination is therefore irreversibility, which separates it from earlier states in which the cell's fate is still flexible. (Choice A) is correct because it names the defining property—irreversible commitment to one pathway with loss of access to other fates. (Choice B) is incorrect because it describes a reversible bias, which characterizes earlier, still-flexible specification rather than determination, which is irreversible. (Choice C) is incorrect because the visible change in size, shape, and protein content describes differentiation, "the process by which unspecialized cells become specialized in structure and function," a later morphological step, not the commitment event itself. (Choice D) is incorrect because the partitioning of egg cytoplasm among daughter cells occurs during cleavage, a form of mitotic cell division, and describes division geometry rather than fate commitment. This is a Knowledge of Scientific Concepts and Principles question because it requires recalling the defining property of determination—its irreversibility—and distinguishing that definition from related developmental terms.$ex1$, 'easy', '2C', $cc1$Mechanisms of Development$cc1$, 'biology', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'misconception', $a1B$Confusing irreversible determination with reversible specification$a1B$ FROM q
UNION ALL SELECT id, 'C', 'adjacent_fact', $a1C$Substituting differentiation (morphological specialization) for the commitment event$a1C$ FROM q
UNION ALL SELECT id, 'D', 'process_step_confusion', $a1D$Confusing fate commitment with cleavage/cytoplasm-partitioning geometry$a1D$ FROM q;

-- Q2 [Specification & Determination | easy | Skill 1 | ans B]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Embryogenesis & Development', $sub2$Specification & Determination$sub2$, $qt2$A developmental biologist examines a deuterostome embryonic stem cell that has not yet had its developmental fate programmed. She wants to predict the range of cell types this single undetermined cell is still able to give rise to at this stage.$qt2$, $op2$[{"label": "A", "text": "Its fate was already fixed at fertilization, so it is simply waiting to express a destiny it cannot change."}, {"label": "B", "text": "It retains the ability to develop into any cell type, becoming locked to a specific fate only at a later developmental stage."}, {"label": "C", "text": "It can develop into any cell type, but it permanently loses the ability to divide the moment it commits to a fate."}, {"label": "D", "text": "It can develop only into cells of the tissue layer it already lies nearest to within the embryo."}]$op2$::jsonb, 'B', $ex2$This is a Biology question that falls under the content category 'Mechanisms of Development'. The answer is B because, before its fate is programmed, an undetermined embryonic stem cell still retains the capacity to become any cell type, and that fate is assigned only later in development. The text states that the undetermined cells of deuterostomes are reflected in "embryonic stem cells, which have the ability to develop into any cell type until their fate is programmed at a later developmental stage." Commitment to a single fate is therefore a later event, not a property the cell possesses from the outset, which is why an undetermined cell is described as not yet fully committed at the early cleavage stage. (Choice A) Incorrect because the text places fate programming at "a later developmental stage," not at fertilization, so the fate is not fixed from the start. (Choice B) Correct because the cell "has the ability to develop into any cell type until their fate is programmed at a later developmental stage." (Choice C) Incorrect because losing the ability to divide is not part of determination; the passage links commitment to fate restriction, not to a halt in cell division. (Choice D) Incorrect because being limited to the nearest tissue layer describes a narrower, already-restricted potential rather than the broad capacity of an undetermined cell to become any cell type. This is a Knowledge of Scientific Concepts and Principles question because it requires recalling the defined property of an undetermined embryonic cell before determination.$ex2$, 'easy', '2C', $cc2$Mechanisms of Development$cc2$, 'biology', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'reversed_relationship', $a2A$Reverses the textbook timing of fate programming by placing it at fertilization rather than at a later developmental stage$a2A$ FROM q
UNION ALL SELECT id, 'C', 'misconception', $a2C$Conflates fate commitment with a loss of proliferative capacity, when stem cells continue dividing$a2C$ FROM q
UNION ALL SELECT id, 'D', 'partial_truth', $a2D$Describes the narrower restricted (multipotent-like) potential instead of the broad pre-determination capacity to become any cell type$a2D$ FROM q;

-- Q3 [Specification & Determination | hard | Skill 2 | ans C]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Embryogenesis & Development', $sub3$Specification & Determination$sub3$, $qt3$During normal vertebrate limb development, web-like tissue initially connects the developing digits. A researcher applies an agent that selectively blocks the cell-signaling mechanism that would normally trigger programmed cell death in this interdigital tissue and lets the embryo develop further. She predicts the effect on the digits.$qt3$, $op3$[{"label": "A", "text": "The interdigital cells die anyway through accidental cell death, but their rupture provokes inflammation that fuses the adjacent digits together."}, {"label": "B", "text": "The interdigital cells are removed even faster, because blocking the programmed-death signal forces those cells to self-destruct ahead of schedule."}, {"label": "C", "text": "The interdigital cells are not eliminated, so the web-like tissue persists and the digits remain joined rather than fully separating."}, {"label": "D", "text": "The interdigital cells proliferate into new digits, because the blocked death signal is what normally limits how many fingers and toes form."}]$op3$::jsonb, 'C', $ex3$This is a Biology question that falls under the content category 'Mechanisms of Development'. The answer is C because the separation of digits depends on apoptosis actively removing the interdigital cells, so blocking the death signal leaves that tissue in place and the digits stay joined. The text states that "early stages of development include the formation of web-like tissue between individual fingers and toes" and that "during the course of normal development, these unneeded cells must be eliminated, enabling fully separated fingers and toes to form," with "a cell signaling mechanism" that "triggers apoptosis, which destroys the cells between the developing digits" (Bio lines 11821-11832). If that signaling-triggered apoptosis is blocked, the cells are not destroyed, so the web persists and the digits cannot fully separate. (Choice A) is wrong because apoptosis is a controlled death that "prevents the release of potentially damaging molecules," whereas necrosis is the accidental death that "causes inflammation"; blocking apoptosis does not convert the cells to inflammatory necrosis on schedule (Bio lines 11802-11803; A&P lines 7222-7224). (Choice B) is wrong because blocking the death-triggering signal removes the stimulus for self-destruction rather than accelerating it. (Choice C) is correct because apoptosis is the mechanism that sculpts away the interdigital web, so preventing it leaves the digits joined. (Choice D) is wrong because the signal triggers cell death, not cell proliferation, so blocking it cannot generate extra digits. This is a Scientific Reasoning and Problem Solving question because it requires predicting a developmental phenotype from a perturbation of the apoptotic signaling mechanism that normally sculpts the limb.$ex3$, 'hard', '2C', $cc3$Mechanisms of Development$cc3$, 'biology', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a3A$Conflates blocked apoptosis with necrosis, assuming the cells die anyway via accidental, inflammation-causing death that then fuses the digits$a3A$ FROM q
UNION ALL SELECT id, 'B', 'reversed_relationship', $a3B$Reverses the effect of blocking the death signal, claiming inhibition accelerates self-destruction rather than preventing it$a3B$ FROM q
UNION ALL SELECT id, 'D', 'process_step_confusion', $a3D$Confuses the developmental step apoptosis performs (removing cells) with proliferation, treating the death signal as a limiter on digit number$a3D$ FROM q;

-- Q4 [Specification & Determination | medium | Skill 2 | ans D]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Embryogenesis & Development', $sub4$Specification & Determination$sub4$, $qt4$During limb-bud development, a secreting region at the posterior margin releases a signaling protein that diffuses across the bud, and cells positioned at increasing distances from this source go on to form structurally distinct digits. A researcher predicts that the digit a given cell forms is set by how much of the protein that cell detects. Which observation, if made, would most directly support this prediction?$qt4$, $op4$[{"label": "A", "text": "Every cell across the bud detects an identical protein level, and the differing digits trace to differences in each cell's DNA sequence."}, {"label": "B", "text": "The protein physically displaces cells toward the source, and each cell's digit identity follows from where it is pushed."}, {"label": "C", "text": "A cell adopts its digit identity only after the protein around it has dropped to zero and the signal is gone entirely."}, {"label": "D", "text": "Cells nearer the source, sitting in higher protein concentration, adopt one digit identity while cells farther away, in lower concentration, adopt another."}]$op4$::jsonb, 'D', $ex4$This is a Biology question that falls under the content category 'Mechanisms of Development'. The answer is D because a morphogen forms a concentration gradient from its source, so a cell's distance from the source sets the dose it reads, and that position-dependent dose is what assigns its fate. Cells of one tissue share the same genome, so the differing identities cannot come from DNA-sequence differences; instead the gradient supplies positional information that downstream regulators read out. Hox/homeobox transcription factors then execute that information along the body axis, since they "encode transcription factors that control the expression of numerous other genes" and their order "reflects the anterior-posterior axis of the animal's body" (Bio 33305-33309). Observing higher-concentration cells become one digit and lower-concentration cells become another is exactly the dose-to-fate relationship the prediction requires. (Choice A) is incorrect because the cells of one developing field share the same genome, so identical exposure could not yield different digits, and sequence differences are not the source of positional information. (Choice B) is incorrect because it confuses mechanical shoving with concentration-dependent signaling; the cell reads how much signal is present, not where it is pushed. (Choice C) is incorrect because fate is specified by the level of signal present, not by the signal's complete removal; requiring zero concentration reverses the actual relationship. (Choice D) is correct because it links distance from the source to detected dose to digit identity, the gradient-based positional mechanism. This is a Scientific Reasoning and Problem Solving question because it requires evaluating which experimental observation would support a proposed dose-to-fate mechanism rather than recalling a stated fact.$ex4$, 'medium', '2C', $cc4$Mechanisms of Development$cc4$, 'biology', 2, 105
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a4A$cells of a tissue carry different DNA sequences that determine fate, rather than a shared genome read out by a gradient$a4A$ FROM q
UNION ALL SELECT id, 'B', 'process_step_confusion', $a4B$confuses mechanical movement/positioning with concentration-dependent chemical signaling$a4B$ FROM q
UNION ALL SELECT id, 'C', 'reversed_relationship', $a4C$fate set by complete absence of signal rather than by the level of signal present$a4C$ FROM q;

-- Q5 [Specification & Determination | hard | Skill 2 | ans A]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Embryogenesis & Development', $sub5$Specification & Determination$sub5$, $qt5$A developmental biologist transplants a cell that has already become irreversibly determined for an anterior fate into a posterior region of the same embryo, where the local morphogen concentration is much higher and normally specifies a posterior fate. A still-uncommitted neighbor placed alongside it adopts the posterior fate dictated by the new dose. She predicts the developmental outcome of the transplanted, already-determined cell.$qt5$, $op5$[{"label": "A", "text": "It develops into its original anterior fate, ignoring the higher local morphogen dose, because determination is an irreversible commitment the new positional signal cannot override."}, {"label": "B", "text": "It re-specifies to the posterior fate set by the higher morphogen dose, because cells continuously read morphogen concentration to assign their fate."}, {"label": "C", "text": "It reverts to an undetermined state and regains the ability to become any cell type in the embryo before responding to the new dose."}, {"label": "D", "text": "It forms a fate intermediate between its anterior and the posterior one, blending the two positional morphogen signals it has experienced."}]$op5$::jsonb, 'A', $ex5$This is a Biology question that falls under the content category 'Mechanisms of Development'. The answer is A because once a cell is determined, that commitment is irreversible, so a new positional (morphogen) dose can no longer redirect its fate. The text states that for a determined cell, "A given cell does not have the ability to develop into any cell type other than its original destination" (Bio p.33580), and that cells become "irreversibly committed to a developmental pathway" (A&P p.6285); only cells whose "fate is programmed at a later developmental stage" remain able to "develop into any cell type" while still undetermined (Bio p.33589). The uncommitted neighbor still reads the new dose and adopts the posterior fate, but the determined cell is locked, so it forms its original anterior structure despite the higher morphogen concentration. (Choice A) is correct: the irreversibly determined cell keeps its original anterior fate even in the new high-dose environment. (Choice B) is the 510-tempting trap because reading morphogen dose to set fate is true for cells before determination, but a determined cell can no longer be re-specified. (Choice C) is wrong because a new environment does not erase determination or restore full potency; only still-undetermined cells retain that flexibility (Bio p.33589). (Choice D) is wrong because a determined cell is locked to one fate rather than blending two positional signals, even though morphogens otherwise act dose-dependently. This is a Scientific Reasoning and Problem Solving question because it requires chaining the morphogen-dose concept with the irreversibility of determination to predict the divergent outcomes of a determined cell versus its uncommitted neighbor in a transplant scenario.$ex5$, 'hard', '2C', $cc5$Mechanisms of Development$cc5$, 'biology', 2, 160
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'partial_truth', $a5B$True-before-determination dose-reading rule misapplied to an already-determined cell (510-tempting)$a5B$ FROM q
UNION ALL SELECT id, 'C', 'misconception', $a5C$New environment supposedly erases determination and restores full potency$a5C$ FROM q
UNION ALL SELECT id, 'D', 'partial_truth', $a5D$Dose-dependent morphogen action misread as a blended intermediate fate in a locked cell$a5D$ FROM q;

-- Q6 [Differentiation & Stem-Cell Potency | easy | Skill 1 | ans B]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Embryogenesis & Development', $sub6$Differentiation & Stem-Cell Potency$sub6$, $qt6$A researcher isolates a population of cells from human bone marrow and observes that the cells proliferate continuously in culture and, when exposed to particular signaling conditions, give rise to several distinct specialized cell types. Based on these properties, the researcher classifies the isolated cells as stem cells.$qt6$, $op6$[{"label": "A", "text": "A fully specialized cell that has permanently exited the cell cycle and can no longer divide"}, {"label": "B", "text": "An unspecialized cell that can divide without limit and, under specific conditions, differentiate into specialized cell types"}, {"label": "C", "text": "A cell whose genome has been physically reduced so that it carries only the genes needed for one tissue"}, {"label": "D", "text": "A cell that forms only when a specialized cell loses its identity, so it cannot itself produce more stem cells"}]$op6$::jsonb, 'B', $ex6$This is a Biology question that falls under the content category 'Mechanisms of Development'. The answer is B because a stem cell is defined as an unspecialized cell that can divide without limit and, under specific conditions, differentiate into specialized cell types. The textbook states that "A stem cell is an unspecialized cell that can divide without limit as needed and can, under specific conditions, differentiate into specialized cells." The two properties the researcher observes—continuous proliferation and the capacity to give rise to multiple specialized cell types under particular signals—are precisely the two defining features of a stem cell. The textbook further notes that stem cells "continually divide and regenerate new stem cells instead of further specializing," confirming their self-renewal capacity. (Choice A) A fully specialized cell that has permanently exited the cell cycle describes a terminally differentiated (unipotent) end cell, which contradicts the requirement that a stem cell "divide without limit." (Choice B) is correct because it captures both defining properties—unlimited division and conditional differentiation into specialized cells—exactly as the text states. (Choice C) is incorrect because the genome is retained, not deleted: "all cells in the body... contain the same DNA," and differentiation arises from selective gene expression rather than physical loss of genes. (Choice D) is incorrect because stem cells "continually divide and regenerate new stem cells" (self-renewal); they are not products of a specialized cell reverting and losing the ability to make more stem cells. This is a Knowledge of Scientific Concepts and Principles question because it requires recalling the textbook definition and defining properties of a stem cell.$ex6$, 'easy', '2C', $cc6$Mechanisms of Development$cc6$, 'biology', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a6A$Confuses a stem cell with a terminally differentiated/unipotent end cell that can no longer divide$a6A$ FROM q
UNION ALL SELECT id, 'C', 'adjacent_fact', $a6C$Assumes differentiation involves physical genome reduction rather than retained DNA with selective expression$a6C$ FROM q
UNION ALL SELECT id, 'D', 'reversed_relationship', $a6D$Reverses self-renewal by casting the stem cell as a reversion product unable to regenerate more stem cells$a6D$ FROM q;

-- Q7 [Differentiation & Stem-Cell Potency | medium | Skill 2 | ans C]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Embryogenesis & Development', $sub7$Differentiation & Stem-Cell Potency$sub7$, $qt7$A single patient's neuron and hepatocyte are sequenced and found to share an identical genome, yet the two cells synthesize almost entirely different sets of proteins. A researcher asks what accounts for the divergence in protein output between the two fully differentiated cell types.$qt7$, $op7$[{"label": "A", "text": "During differentiation, each cell permanently deleted the genes it would never need, so the neuron and hepatocyte now carry smaller, tissue-specific genomes."}, {"label": "B", "text": "The neuron and hepatocyte inherited different DNA sequences from the zygote, and their differing protein outputs simply follow from that sequence difference."}, {"label": "C", "text": "Both cells retain the identical genome, but each transcribes only the subset of genes relevant to its own function, so different proteins are produced."}, {"label": "D", "text": "Transcription factors mutate the relevant genes in each cell so that only the altered, active genes can be read, distinguishing the two cell types."}]$op7$::jsonb, 'C', $ex7$This is a Biology question that falls under the content category 'Mechanisms of Development'. The answer is C because differentiation arises from selective gene expression, not from any change to the underlying DNA: every somatic cell keeps the full, identical genome, and specialization comes from each cell transcribing only the portion of that genome its function requires. The A&P text states that "all cells in the body, beginning with the fertilized egg, contain the same DNA" and that "each type of cell only 'reads' the portions of DNA that are relevant to its own function," while the Biology text adds that "each cell does not turn on, or express, the same set of genes." Because the neuron and hepatocyte share a sequence but express different gene subsets, they build different proteins. (Choice A) is wrong because somatic cells "generally" retain the complete DNA rather than deleting unused genes during differentiation. (Choice B) is wrong because the two cells share the same DNA sequence inherited from the fertilized egg; expression—not sequence—differs. (Choice C) is correct because the identical genome is differentially transcribed, yielding cell-type-specific proteins. (Choice D) is wrong because transcription factors "either promote or inhibit" transcription—they regulate gene reading without mutating the genes. This is a Scientific Reasoning and Problem Solving question because it requires using observed data (identical genome but divergent protein output) to infer the underlying mechanism of differentiation rather than simply recalling a definition.$ex7$, 'medium', '2C', $cc7$Mechanisms of Development$cc7$, 'biology', 2, 105
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a7A$Differentiation deletes unused genes, shrinking the genome$a7A$ FROM q
UNION ALL SELECT id, 'B', 'reversed_relationship', $a7B$Sequence difference (not expression) drives cell identity$a7B$ FROM q
UNION ALL SELECT id, 'D', 'partial_truth', $a7D$Transcription factors mutate rather than regulate genes$a7D$ FROM q;

-- Q8 [Differentiation & Stem-Cell Potency | medium | Skill 2 | ans D]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Embryogenesis & Development', $sub8$Differentiation & Stem-Cell Potency$sub8$, $qt8$A hematologist isolates a single adult bone-marrow stem cell and shows that its progeny mature into erythrocytes, leukocytes, and platelets, yet none of its daughters ever become muscle, neurons, or endothelium. The hematologist needs to assign this cell to a potency class.$qt8$, $op8$[{"label": "A", "text": "Pluripotent, because it produces several distinct mature cell types from one founding cell"}, {"label": "B", "text": "Totipotent, because it generates every formed element that circulates in the blood"}, {"label": "C", "text": "Unipotent, because its output is confined to the blood and thus to one functional role"}, {"label": "D", "text": "Multipotent, because it differentiates into several cell types within a single related lineage"}]$op8$::jsonb, 'D', $ex8$This is a Biology question that falls under the content category 'Mechanisms of Development'. The answer is D because a hematopoietic stem cell yields several distinct cell types, but all of them belong to one related cell lineage (the blood lineage), which is the defining feature of a multipotent cell. OpenStax Anatomy & Physiology 2e states that "A multipotent stem cell has the potential to differentiate into different types of cells within a given cell lineage or small number of lineages, such as a red blood cell or white blood cell," and identifies the bone-marrow "hematopoietic stem cells, which give rise to red blood cells, white blood cells, and platelets" as exactly this kind of multipotent cell. The cell makes multiple cell types (ruling out unipotent) but stays inside the blood lineage and cannot form arbitrary tissues or a whole organism (ruling out pluripotent and totipotent). (Choice A) Pluripotent is reserved for a cell with "the potential to differentiate into any type of human tissue," far broader than a single blood lineage, so it overstates this cell's potency. (Choice B) Totipotent cells can form "any of the cells needed to enable an organism to grow and develop," including extraembryonic tissue, not merely the formed elements of blood. (Choice C) Unipotent is wrong because a unipotent cell "can only reproduce to generate more of its own specific cell type," whereas this cell makes several different blood cell types. (Choice D) Multipotent is correct because the cell differentiates into several cell types restricted to one related lineage, matching the textbook description of hematopoietic stem cells. This is a Scientific Reasoning and Problem Solving question because it requires applying the operational definitions of potency to an observed differentiation pattern and excluding three near-miss classes to arrive at the correct classification.$ex8$, 'medium', '2C', $cc8$Mechanisms of Development$cc8$, 'biology', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'adjacent_fact', $a8A$Confusing the next-higher potency tier (pluripotent) by counting 'several mature cell types' without checking lineage breadth$a8A$ FROM q
UNION ALL SELECT id, 'B', 'scale_unit_error', $a8B$Inflating scope to the highest tier (totipotent) by treating 'all blood elements' as 'all cells'$a8B$ FROM q
UNION ALL SELECT id, 'C', 'partial_truth', $a8C$Correctly noting blood restriction but wrongly collapsing multiple cell types into one (unipotent)$a8C$ FROM q;

-- Q9 [Differentiation & Stem-Cell Potency | hard | Skill 2 | ans A]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Embryogenesis & Development', $sub9$Differentiation & Stem-Cell Potency$sub9$, $qt9$A research team reprograms a patient's skin fibroblasts, and the resulting cells reliably differentiate in culture into neurons (ectoderm), cardiac muscle (mesoderm), and pancreatic acinar cells (endoderm). When a single such cell is injected into a mouse blastocyst, it contributes to the embryo proper but never gives rise to placental trophoblast, and it cannot on its own generate a viable, complete organism. The team should classify these reprogrammed cells as:$qt9$, $op9$[{"label": "A", "text": "pluripotent, because they form derivatives of all three germ layers yet cannot support full development of an organism, such as building a placenta"}, {"label": "B", "text": "totipotent, because they give rise to every cell type the body needs to grow and develop into a complete organism"}, {"label": "C", "text": "multipotent, because they are limited to the differentiated cell types of the single tissue lineage they were derived from"}, {"label": "D", "text": "oligopotent, because they give rise to only a few of the embryonic cell types found across the germ layers"}]$op9$::jsonb, 'A', $ex9$This is a Biology question that falls under the content category 'Mechanisms of Development'. The answer is A because a cell that can become any embryonic tissue from all three germ layers but cannot sustain a whole organism sits exactly at the pluripotent rung of the potency hierarchy. The A&P 2e text defines a pluripotent stem cell as one that "has the potential to differentiate into any type of human tissue but cannot support the full development of an organism" (L5635-5636), and it describes induced pluripotent stem cells (iPSCs) reprogrammed from adult cells as "capable of generating cells characteristic of all three germ layers" (L5703-5704). The scenario's cells meet both marks: they generate ectoderm, mesoderm, and endoderm derivatives, but their inability to form placental trophoblast or a complete organism rules out the higher totipotent rung. Reaching all three germ layers is therefore necessary but not sufficient for totipotency, which additionally requires the capacity to build extraembryonic structures and a whole organism. (Choice A) Correct: forming all three germ layers while failing to support full organismal development, including the placenta, is the precise definition of pluripotent. (Choice B) Incorrect: totipotent cells form the cells "needed to enable an organism to grow and develop" (L5631-5632), including the placenta and a complete organism, which these cells cannot do, so the all-germ-layer result alone does not reach totipotency. (Choice C) Incorrect: multipotent cells are confined to "a given cell lineage or small number of lineages" (L5639-5640), whereas a cell making all three germ layers far exceeds a single tissue lineage. (Choice D) Incorrect: an oligopotent cell "is limited to becoming one of a few different cell types" (L5642-5643), a range far narrower than derivatives of all three germ layers. This is a Scientific Reasoning and Problem Solving question because it requires interpreting an experimental differentiation result against the operational criteria that separate adjacent potency classes and ruling out the tempting totipotent assignment using the missing placental/whole-organism capability.$ex9$, 'hard', '2C', $cc9$Mechanisms of Development$cc9$, 'biology', 2, 160
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'partial_truth', $a9B$Mistaking all-three-germ-layer potential for totipotency by ignoring the extraembryonic/whole-organism requirement$a9B$ FROM q
UNION ALL SELECT id, 'C', 'adjacent_fact', $a9C$Applying the correct definition of a different (lower) potency tier, multipotency confined to one lineage$a9C$ FROM q
UNION ALL SELECT id, 'D', 'scale_unit_error', $a9D$Understating the breadth of differentiation potential by assigning a 'few cell types' tier to a cell spanning all three germ layers$a9D$ FROM q;

-- Q10 [Differentiation & Stem-Cell Potency | hard | Skill 2 | ans B]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Embryogenesis & Development', $sub10$Differentiation & Stem-Cell Potency$sub10$, $qt10$An embryologist isolates two single cells from one human conceptus: cell X is taken from the two-cell stage just after the zygote's first division, and cell Y is taken from the inner cell mass of the later blastocyst. Each cell is separately given the cues needed to support development. Which outcome should the embryologist predict?$qt10$, $op10$[{"label": "A", "text": "Both cells can regenerate every fetal germ layer and the placenta, so either one alone could give rise to a complete organism."}, {"label": "B", "text": "Cell X can form both the embryo proper and the placenta and could yield a complete organism, whereas cell Y cannot generate the placenta."}, {"label": "C", "text": "Cell Y is the more potent of the two and can generate the placenta and a complete organism, whereas cell X cannot form extraembryonic tissue."}, {"label": "D", "text": "Cell X is pluripotent and cell Y is totipotent, so cell Y has the broader differentiation potential and alone supports full development."}]$op10$::jsonb, 'B', $ex10$This is a Biology question that falls under the content category 'Mechanisms of Development'. The answer is B because the earliest post-zygotic cells (cell X) are totipotent and can give rise to both the embryo proper and the extraembryonic placental tissue, whereas inner-cell-mass cells (cell Y) are only pluripotent and cannot support full development. The text states that "the first embryonic cells that arise from the division of the zygote are the ultimate stem cells... described as totipotent because they have the potential to differentiate into any of the cells needed to enable an organism to grow and develop," and the glossary defines totipotent cells as those that "differentiate into any type of cell and organ in the body." By contrast, the pluripotent cells that "develop from totipotent stem cells" can form "any type of human tissue but cannot support the full development of an organism," so cell Y cannot build the placenta. The single distinguishing variable is the capacity to form extraembryonic (placental) tissue and thereby a complete organism, which only the totipotent cell retains. (Choice A) is wrong because forming every germ layer does not equal totipotency; the pluripotent cell Y "cannot support the full development of an organism" and therefore cannot rebuild the placenta. (Choice B) is correct because only the totipotent cell X can produce both embryonic and extraembryonic tissue and support a complete organism. (Choice C) reverses the relationship: potency decreases over developmental time, as pluripotent cells "develop from totipotent stem cells" and become "more specialized," so the later cell Y is less potent, not more. (Choice D) mislabels the hierarchy; totipotent ranks above pluripotent, so cell X (earliest) is the totipotent one and cell Y is pluripotent. This is a Scientific Reasoning and Problem Solving question because it requires applying the potency hierarchy to a novel two-cell scenario and predicting which isolated cell can generate extraembryonic tissue and a complete organism.$ex10$, 'hard', '2C', $cc10$Mechanisms of Development$cc10$, 'biology', 2, 160
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'partial_truth', $a10A$Both populations equivalent because each can form the three germ layers, so either could rebuild the placenta$a10A$ FROM q
UNION ALL SELECT id, 'C', 'reversed_relationship', $a10C$Later inner-cell-mass cell treated as more potent because it formed later and accumulated extraembryonic capacity$a10C$ FROM q
UNION ALL SELECT id, 'D', 'adjacent_fact', $a10D$Hierarchy mislabeled with pluripotent as the broadest/highest category above totipotent$a10D$ FROM q;

-- Q11 [Cell-Cell Communication | easy | Skill 1 | ans C]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Embryogenesis & Development', $sub11$Cell-Cell Communication$sub11$, $qt11$A physiologist studies the thyroid gland, which secretes thyroid hormone into the surrounding capillary network so that the hormone is carried throughout the body to act on target cells in distant organs such as the liver and skeletal muscle. The mode of chemical signaling defined by the long distance the ligand travels to reach these targets is identified as:$qt11$, $op11$[{"label": "A", "text": "paracrine signaling, in which the secreted ligand diffuses only a short distance through the extracellular matrix to act on immediately neighboring cells"}, {"label": "B", "text": "autocrine signaling, in which the secreting cell bears the receptor and the ligand binds back to and acts on the same cell that released it"}, {"label": "C", "text": "endocrine signaling, in which the secreted ligand is a hormone that travels through the bloodstream to reach and act on distant target cells"}, {"label": "D", "text": "direct signaling through gap junctions, in which small molecules and ions pass through channels straight into the cytoplasm of a physically adjacent cell"}]$op11$::jsonb, 'C', $ex11$This is a Biology question that falls under the content category 'Mechanisms of Development'. The answer is C because the defining feature of endocrine signaling is that the secreted ligand is a hormone that is carried over a long distance through the bloodstream to act on distant target cells. The text states that "Signals from distant cells are called endocrine signals" and that "Hormones travel the large distances between endocrine cells and their target cells via the bloodstream," which exactly matches the thyroid gland releasing hormone into the circulation to reach the liver and skeletal muscle. The four categories of chemical signaling differ mainly in "the distance that the signal travels through the organism to reach the target cell," and the long, bloodstream-mediated distance described in the scenario uniquely identifies the endocrine mode. (Choice A) Paracrine signaling is incorrect because paracrine signals act locally between nearby cells and "move by diffusion through the extracellular matrix," not over the long distances described. (Choice B) Autocrine signaling is incorrect because in autocrine signaling the signaling cell "can also bind to the ligand that is released," so the target is the same or a similar cell rather than a distant organ. (Choice C) Endocrine signaling is correct because the hormone travels "the large distances between endocrine cells and their target cells via the bloodstream" to act on distant targets, matching the thyroid scenario. (Choice D) Direct signaling across gap junctions is incorrect because those "fluid-filled channels allow small signaling molecules... to diffuse between the two cells" that are physically adjacent, not across long distances through the blood. This is a Knowledge of Scientific Concepts and Principles question because it requires recalling the definition of endocrine signaling and matching it to the distance the signal travels.$ex11$, 'easy', '2C', $cc11$Mechanisms of Development$cc11$, 'biology', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'adjacent_fact', $a11A$Names a real, neighboring signaling mode (paracrine) but with short-range extracellular-matrix diffusion instead of long-range bloodstream transport$a11A$ FROM q
UNION ALL SELECT id, 'B', 'adjacent_fact', $a11B$Names a real signaling mode (autocrine) defined by self-targeting rather than the distance-to-distant-cells variable that defines the key$a11B$ FROM q
UNION ALL SELECT id, 'D', 'adjacent_fact', $a11D$Names a real signaling mode (gap-junction/direct) requiring physical adjacency, the opposite extreme of the long-distance variable that defines endocrine signaling$a11D$ FROM q;

-- Q12 [Cell-Cell Communication | medium | Skill 2 | ans D]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Embryogenesis & Development', $sub12$Cell-Cell Communication$sub12$, $qt12$A cultured fibroblast continuously secretes a growth factor into its medium and simultaneously displays the membrane receptor for that same factor on its own surface; when an antibody that occupies the secreted factor's binding site is added, the cell stops dividing. A researcher analyzing this result concludes that the cell's proliferation is being driven by a particular mode of chemical signaling. Which mode does the evidence most directly support?$qt12$, $op12$[{"label": "A", "text": "Paracrine signaling, because the factor diffuses a short distance through the extracellular matrix to stimulate other nearby cells."}, {"label": "B", "text": "Endocrine signaling, because the secreted factor is a hormone carried through the bloodstream to distant target cells."}, {"label": "C", "text": "Juxtacrine signaling, because a membrane-anchored ligand on the cell binds a receptor only on a directly contacting neighbor."}, {"label": "D", "text": "Autocrine signaling, because the cell that releases the ligand also carries the receptor that binds it."}]$op12$::jsonb, 'D', $ex12$This is a Biology question that falls under the content category 'Mechanisms of Development'. The answer is D because autocrine signaling is defined by a cell that both releases a ligand and bears the receptor that binds it, so it signals to itself. The text states, "Autocrine signals are produced by signaling cells that can also bind to the ligand that is released. This means the signaling cell and the target cell can be the same or a similar cell (the prefix auto- means self...)." In the scenario, the same fibroblast secretes the factor and displays its receptor, and blocking the factor's binding site halts its own division—the receiving cell is the secreting cell, which is the defining feature of autocrine signaling and a common mechanism in early development. The single defining variable separating the key from each distractor is the identity of the responding cell (self) versus another cell. (Choice A) Paracrine signaling acts on a different, nearby cell ("Signals that act locally between cells that are close together are called paracrine signals"), not on the secreting cell itself. (Choice B) Endocrine signaling uses hormones carried "via the bloodstream" to "distant" targets, which does not fit a single cultured cell responding to factor in its own medium. (Choice C) Juxtacrine/direct contact signaling requires a separate, directly touching neighbor cell, whereas here the responder is the secretor. (Choice D) Autocrine signaling is correct because the secreting cell carries the receptor for, and responds to, its own released ligand. This is a Scientific Reasoning and Problem Solving question because it requires interpreting experimental evidence (co-expression of ligand and receptor plus loss of division on blockade) to infer which signaling mode is operating rather than recalling a definition.$ex12$, 'medium', '2C', $cc12$Mechanisms of Development$cc12$, 'biology', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'adjacent_fact', $a12A$Confusing autocrine with the neighboring-cell case of paracrine/local signaling$a12A$ FROM q
UNION ALL SELECT id, 'B', 'misconception', $a12B$Treating any secreted growth factor as a bloodstream-borne hormone (endocrine)$a12B$ FROM q
UNION ALL SELECT id, 'C', 'adjacent_fact', $a12C$Mistaking self-signaling for direct contact-dependent signaling to a touching neighbor$a12C$ FROM q;

-- Q13 [Cell-Cell Communication | medium | Skill 2 | ans A]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Embryogenesis & Development', $sub13$Cell-Cell Communication$sub13$, $qt13$A developmental biologist measures the spread of a newly secreted signaling protein and finds that it activates target receptors only on cells immediately adjacent to the source, is rapidly broken down by enzymes in the extracellular space, and never alters the behavior of tissue more than a few cell diameters away. From these data, which signaling mode and explanation best account for the confined response?$qt13$, $op13$[{"label": "A", "text": "Paracrine signaling, because the ligand diffuses only locally through the extracellular matrix and is quickly degraded, keeping the response confined to nearby cells."}, {"label": "B", "text": "Endocrine signaling, because the ligand is a hormone diluted into the bloodstream that produces a slow, long-lasting response in distant target cells."}, {"label": "C", "text": "Autocrine signaling, because the releasing cell carries the matching receptor and the ligand binds back to act on that same cell."}, {"label": "D", "text": "Direct signaling through gap junctions, because small intracellular mediators pass through channels directly between the cytoplasm of adjacent cells without entering the matrix."}]$op13$::jsonb, 'A', $ex13$This is a Biology question that falls under the content category 'Mechanisms of Development'. The answer is A because the data show a secreted ligand that diffuses only to immediately adjacent cells, is rapidly destroyed by extracellular enzymes, and leaves distant tissue unaffected, which is the defining profile of paracrine signaling. OpenStax states that "Signals that act locally between cells that are close together are called paracrine signals" and that they "move by diffusion through the extracellular matrix," and that "In order to keep the response localized, paracrine ligand molecules are normally quickly degraded by enzymes or removed by neighboring cells." Short-range diffusion through the matrix explains why only neighbors are reached, and enzymatic degradation explains why the signal cannot accumulate and travel to distant tissue, so both observations are accounted for by a single mode. (Choice A) is correct because local matrix diffusion plus rapid enzymatic degradation together confine the response to nearby cells. (Choice B) is wrong because endocrine signals are hormones carried "via the bloodstream" that "become diluted" and "produce a slower response but have a longer-lasting effect" on distant cells, which contradicts the observed local, matrix-limited spread. (Choice C) is wrong because autocrine signaling requires that the "signaling cell and the target cell can be the same," yet the data show the factor acting on adjacent cells, not back on the source. (Choice D) is wrong because gap-junction signaling moves "intracellular mediators" directly "between the two cells" through channels rather than as a secreted molecule diffusing through and degraded in the extracellular matrix. This is a Scientific Reasoning and Problem Solving question because it requires interpreting experimental observations about ligand range and stability and inferring the underlying signaling mechanism rather than recalling a definition.$ex13$, 'medium', '2C', $cc13$Mechanisms of Development$cc13$, 'biology', 2, 105
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'adjacent_fact', $a13B$Names a real signaling mode (endocrine) but uses bloodstream transport, dilution, and a slow long-lasting distant response that contradicts the observed local, rapidly degraded behavior$a13B$ FROM q
UNION ALL SELECT id, 'C', 'misconception', $a13C$Confuses paracrine with autocrine by assuming the secreting cell receives its own signal, ignoring that the data show action on adjacent cells$a13C$ FROM q
UNION ALL SELECT id, 'D', 'process_step_confusion', $a13D$Swaps secreted extracellular-matrix diffusion for direct cytoplasm-to-cytoplasm transfer of intracellular mediators through gap junction channels$a13D$ FROM q;

-- Q14 [Cell-Cell Communication | hard | Skill 2 | ans B]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Embryogenesis & Development', $sub14$Cell-Cell Communication$sub14$, $qt14$A developmental biologist grafts dorsal "organizer" cells from a donor amphibian embryo into the ventral (belly) region of a host embryo and observes that a complete second notochord and body axis develops at the graft site. Lineage labeling reveals that most of the cells making up this second axis carry the host's marker, not the donor's. What does this result most strongly indicate about how the second axis forms?$qt14$, $op14$[{"label": "A", "text": "The second notochord is built entirely from the dividing descendants of the grafted dorsal cells, which proliferate in place without instructing any surrounding host tissue."}, {"label": "B", "text": "The grafted dorsal cells act as a local inducer, signaling competent neighboring host cells to change fate, so most of the second axis is built from recruited host tissue."}, {"label": "C", "text": "The grafted dorsal cells anchor to the host belly cells through gap junctions, and the passage of ions such as Ca2+ directly between the cytoplasms drives the host cells to form a notochord."}, {"label": "D", "text": "The grafted dorsal cells release a hormone into the embryo's bloodstream that travels to and respecifies distant host cells into notochord tissue."}]$op14$::jsonb, 'B', $ex14$This is a Biology question that falls under the content category 'Mechanisms of Development'. The answer is B because the host-derived marker dominating the second axis shows the graft did not build the structure itself but instead signaled nearby host cells to change their fate, the defining feature of induction. Local, short-range signaling of this kind is paracrine: signals "move by diffusion through the extracellular matrix" to "neighboring cells," and in embryological development "this process of stimulating a group of neighboring cells may help to direct the differentiation of identical cells." The host cells could respond because, at this stage, they are still competent and "not yet fully committed... to develop into specific cell types," so "adjacent cells are able to compensate" and adopt new fates; the graft supplies the instructive signal rather than the cellular building blocks. (Choice A) is the reversed reading in which the inducer is treated as the sole responder; it is contradicted by the lineage data showing the axis is mostly host-derived, not donor-derived. (Choice B) is correct because the host-marked second axis reflects competent host cells responding to an inductive signal released by the graft. (Choice C) confuses paracrine induction with gap-junction signaling, which only lets "small molecules or ions, such as calcium ions (Ca2+)" pass between adjacent cells while "large molecules like proteins and DNA cannot fit," and cannot account for instructing a whole field of cells to build an axis. (Choice D) misapplies endocrine signaling, in which "hormones travel the large distances between endocrine cells and their target cells via the bloodstream," whereas this is a strictly local effect at the graft site. This is a Scientific Reasoning and Problem Solving question because it requires interpreting an experimental graft-and-lineage result to infer the underlying signaling mechanism rather than recalling a stated fact.$ex14$, 'hard', '2C', $cc14$Mechanisms of Development$cc14$, 'biology', 2, 160
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'reversed_relationship', $a14A$Inducer-and-responder roles swapped: the signaling graft is recast as the tissue that physically builds the structure, ignoring the host-derived lineage data$a14A$ FROM q
UNION ALL SELECT id, 'C', 'process_step_confusion', $a14C$Substitutes direct gap-junction ion transfer for paracrine diffusible induction as the mechanism that changes responder fate$a14C$ FROM q
UNION ALL SELECT id, 'D', 'adjacent_fact', $a14D$Imports a real but wrong signaling mode—bloodstream-borne endocrine/hormone signaling—for what is actually a local effect$a14D$ FROM q;

-- Q15 [Cell-Cell Communication | hard | Skill 2 | ans C]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Embryogenesis & Development', $sub15$Cell-Cell Communication$sub15$, $qt15$A developmental biologist cultures an inducer-cell population and a responder-cell population on opposite sides of a chamber divided by a porous filter that lets molecules dissolved in the surrounding fluid pass through but holds the two populations apart so their membranes never touch. The responder cells fail to differentiate across the filter, yet differentiate normally when the two populations are placed in direct membrane contact. Which mode of chemical signaling is most consistent with this result?$qt15$, $op15$[{"label": "A", "text": "Paracrine signaling, in which the inducer cell releases a ligand that diffuses locally through the extracellular matrix to the responder cells."}, {"label": "B", "text": "Endocrine signaling, in which the inducer cell secretes a hormone that travels a long distance through the circulatory system to the responder cells."}, {"label": "C", "text": "Direct signaling across gap junctions, in which an intracellular mediator passes between the populations only through channels that form where their membranes connect."}, {"label": "D", "text": "Autocrine signaling, in which the inducer cell releases a ligand that binds receptors on the same inducer cell that secreted it."}]$op15$::jsonb, 'C', $ex15$This is a Biology question that falls under the content category 'Mechanisms of Development'. The answer is C because differentiation is abolished by the one thing the filter controls—physical membrane contact—even though the filter still allows molecules dissolved in the surrounding fluid to pass, which points to a signal carried only through channels that form where neighboring membranes connect. The textbook separates the four signaling categories chiefly by how the signal travels: in direct signaling across gap junctions, "fluid-filled channels allow small signaling molecules, called intracellular mediators, to diffuse between the two cells," and these channels are "connections between the plasma membranes of neighboring cells," so the mediator never enters the open extracellular space and cannot cross a filter that blocks membrane contact. By contrast, paracrine, endocrine, and autocrine ligands are all released into the extracellular fluid, so a soluble-permeable filter would not stop them from reaching the other side. Because the response returns only when the membranes connect and the channels can form, the data isolate cytoplasmic continuity through touching membranes—not free diffusion through the fluid—as the necessary variable. (Choice A) A paracrine ligand "move[s] by diffusion through the extracellular matrix," so it would dissolve in the surrounding fluid and freely cross the filter, and the response would not be abolished. (Choice B) Endocrine hormones "travel the large distances between endocrine cells and their target cells via the bloodstream," a soluble long-distance mode that both contradicts the contact requirement and is irrelevant in a chamber with no circulation. (Choice C) Gap-junction signaling transfers an intracellular mediator only through channels between connected membranes, exactly matching a response that fails through the filter but recovers on direct contact. (Choice D) An autocrine signal binds receptors on the same cell that "released" it, so it does not transfer to a separate responder population and cannot explain induction of the neighboring responder cells. This is a Scientific Reasoning and Problem Solving question because it requires interpreting the outcome of a controlled chamber experiment to infer which physical route the inducing signal must take.$ex15$, 'hard', '2C', $cc15$Mechanisms of Development$cc15$, 'biology', 2, 160
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'partial_truth', $a15A$Correctly identifies a local, short-range signaling mode (paracrine) but ignores that a paracrine ligand is released into the extracellular fluid and would diffuse across a soluble-permeable filter, so the response would not be abolished—a 510-tempting trap because both paracrine and gap-junction signaling act between nearby cells.$a15A$ FROM q
UNION ALL SELECT id, 'B', 'adjacent_fact', $a15B$Names a real signaling category (endocrine) that is the wrong scale and route—long-distance, bloodstream-borne—directly contradicting the contact-dependent, no-circulation experimental result.$a15B$ FROM q
UNION ALL SELECT id, 'D', 'misconception', $a15D$Confuses self-signaling (autocrine) with cell-to-cell induction, missing that an autocrine ligand binds the secreting cell itself and is never transferred to a separate responder population.$a15D$ FROM q;

-- Q16 [Cell Migration & Apoptosis | easy | Skill 1 | ans D]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Embryogenesis & Development', $sub16$Cell Migration & Apoptosis$sub16$, $qt16$A researcher compares two dying cells in a tissue sample: one is undergoing apoptosis and the other has died from physical trauma. She predicts that, unlike the traumatized cell, the apoptotic cell will spare neighboring cells from exposure to its hydrolytic enzymes and other potentially harmful contents. What feature of apoptosis accounts for this prediction?$qt16$, $op16$[{"label": "A", "text": "It is accidental cell death from physical injury, so the dying cell spills its contents into the surrounding tissue."}, {"label": "B", "text": "It bursts the cell open so that the immune system is alerted and an inflammatory response is launched."}, {"label": "C", "text": "It can be triggered only by external death-receptor signaling and is never initiated by the cell itself."}, {"label": "D", "text": "It lets the cell die in a controlled manner that prevents the release of potentially damaging molecules from inside the cell."}]$op16$::jsonb, 'D', $ex16$This is a Biology question that falls under the content category 'Mechanisms of Development'. The answer is D because apoptosis is, by definition, a programmed cell-death pathway that dismantles the cell in a regulated way, so its contents are not spilled into the surrounding tissue. OpenStax Biology 2e states that "a cell can initiate a mechanism to trigger programmed cell death, or apoptosis. Apoptosis allows a cell to die in a controlled manner that prevents the release of potentially damaging molecules from inside the cell." This containment is precisely what would spare the neighboring cells in the researcher's prediction, distinguishing apoptosis from a cell ruptured by trauma. (Choice A) describes necrosis, not apoptosis; A&P 2e calls necrosis "accidental cell death" that spills contents and "causes inflammation," which is the reverse of the controlled apoptotic process. (Choice B) is incorrect because apoptosis "does not initiate the inflammatory response," so it does not burst the cell to alert the immune system. (Choice C) is only partly true: external signaling is one route, but the text notes that internal checkpoints can make a cell "spontaneously initiate the process of apoptosis," so self-initiation is also possible. (Choice D) is correct because the defining feature of apoptosis is controlled cell death that prevents release of damaging molecules from inside the cell. This is a Knowledge of Scientific Concepts and Principles question because it requires recalling the textbook-defined feature that distinguishes regulated apoptosis from uncontrolled cell death.$ex16$, 'easy', '2C', $cc16$Mechanisms of Development$cc16$, 'biology', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'reversed_relationship', $a16A$Attributing necrosis (accidental, content-spilling death) to apoptosis, reversing the controlled-vs-uncontrolled relationship$a16A$ FROM q
UNION ALL SELECT id, 'B', 'misconception', $a16B$Believing apoptosis ruptures the cell and triggers inflammation, contradicting that it does not initiate the inflammatory response$a16B$ FROM q
UNION ALL SELECT id, 'C', 'partial_truth', $a16C$Overstating external death-receptor signaling as the sole trigger while ignoring spontaneous internal-checkpoint initiation$a16C$ FROM q;

-- Q17 [Cell Migration & Apoptosis | easy | Skill 1 | ans C]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Embryogenesis & Development', $sub17$Cell Migration & Apoptosis$sub17$, $qt17$During week 3 of human heart development, paired endocardial tubes form within the cardiogenic cords on either side of the embryonic midline. A developmental biologist observes that, over the next several hours, these two tubes converge on the midline. The biologist predicts the immediate next event in building the heart to be:$qt17$, $op17$[{"label": "A", "text": "the two endocardial tubes remain permanently separate, each maturing independently into one of the adult ventricles"}, {"label": "B", "text": "the single heart tube splits by mitosis into two tubes that then drift apart to opposite poles of the embryo"}, {"label": "C", "text": "the two endocardial tubes migrate together and fuse to form a single primitive heart tube"}, {"label": "D", "text": "the endocardial tubes are eliminated by apoptosis and the heart forms instead from an entirely new population of cells"}]$op17$::jsonb, 'C', $ex17$This is a Biology question that falls under the content category 'Mechanisms of Development'. The answer is C because directed cell migration is a normal morphogenetic event: the paired endocardial tubes move toward each other across the midline and fuse into one tube, the structure from which the rest of the heart is built. The text states that the cardiogenic cords develop a lumen to become endocardial tubes and that "The two tubes migrate together and fuse to form a single primitive heart tube," which then "quickly forms five distinct regions." This illustrates the general principle that developing cells migrate to their correct locations to assemble an organ. The single primitive heart tube, not two persisting tubes, is the source of the chambers and great vessels. (Choice A) The tubes do not stay separate to become individual ventricles; the text says they fuse into one tube, and the chambers (the right ventricle from the bulbus cordis, the left from the primitive ventricle) all arise from that one fused tube. (Choice B) Development here proceeds from two tubes fusing into one, not from one tube splitting into two and separating, so this reverses the actual direction of the process. (Choice C) Correct: the two endocardial tubes migrate together and fuse into a single primitive heart tube. (Choice D) Programmed cell death does not remove the endocardial tubes; the migration-and-fusion step described in the text uses these very cells to build the heart rather than discarding them. This is a Knowledge of Scientific Concepts and Principles question because it requires recalling the textbook-described morphogenetic event by which migrating embryonic cells fuse to form the primitive heart tube.$ex17$, 'easy', '2C', $cc17$Mechanisms of Development$cc17$, 'biology', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a17A$Tubes stay separate and each becomes a chamber, missing that they fuse into one tube$a17A$ FROM q
UNION ALL SELECT id, 'B', 'reversed_relationship', $a17B$One tube splits into two (reverses the two-fuse-to-one direction of development)$a17B$ FROM q
UNION ALL SELECT id, 'D', 'process_step_confusion', $a17D$Substitutes apoptosis/replacement for the migration-and-fusion step$a17D$ FROM q;

-- Q18 [Cell Migration & Apoptosis | medium | Skill 2 | ans A]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Embryogenesis & Development', $sub18$Cell Migration & Apoptosis$sub18$, $qt18$A researcher cultures two populations of identical fibroblasts: population 1 is triggered to undergo programmed cell death, while population 2 is killed by mechanical crushing injury. The dying cells from each population are then introduced into separate samples of healthy host tissue. The researcher predicts which sample will mount a local inflammatory response.$qt18$, $op18$[{"label": "A", "text": "The crushed (necrotic) cells provoke local inflammation, whereas the programmed-death (apoptotic) cells do not."}, {"label": "B", "text": "Both populations provoke equally strong local inflammation, because any form of cell death releases the same inflammatory signals."}, {"label": "C", "text": "The programmed-death (apoptotic) cells provoke local inflammation, whereas the crushed (necrotic) cells do not."}, {"label": "D", "text": "Neither population provokes local inflammation, because inflammation arises only in response to invading pathogens."}]$op18$::jsonb, 'A', $ex18$This is a Biology question that falls under the content category 'Mechanisms of Development'. The answer is A because necrosis, the accidental cell death produced by crushing injury, causes inflammation, while apoptosis, the programmed step-by-step death pathway, does not initiate the inflammatory response. The text states that "Necrosis, or accidental cell death, causes inflammation" and that, for apoptosis, "By mechanisms still under investigation, apoptosis does not initiate the inflammatory response." Therefore the population killed by injury (necrosis) is the one that drives a local inflammatory response, and the programmed-death population does not. The distinguishing variable is simply which death pathway is matched to the inflammatory outcome. (Choice A) Correct: the necrotic, injury-killed cells trigger inflammation while the apoptotic cells do not, exactly mirroring the text's pairing of necrosis with inflammation and apoptosis with its absence. (Choice B) Incorrect: this ignores that apoptosis "does not initiate the inflammatory response," so the two populations are not equivalent. (Choice C) Incorrect: this reverses the relationship, assigning inflammation to the programmed (apoptotic) cells, but the text ties inflammation to necrosis, not apoptosis. (Choice D) Incorrect: inflammation is "the standard, initial response of the body to injury" of biological, chemical, physical, or radiation origin, not solely to pathogens, and necrosis from injury does cause it. This is a Scientific Reasoning and Problem Solving question because it requires applying the rule linking necrosis to inflammation and apoptosis to its absence in order to predict the experimental outcome for each cell population.$ex18$, 'medium', '2C', $cc18$Mechanisms of Development$cc18$, 'biology', 2, 105
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'misconception', $a18B$treats all cell death as releasing identical inflammatory signals, ignoring that apoptosis does not initiate inflammation$a18B$ FROM q
UNION ALL SELECT id, 'C', 'reversed_relationship', $a18C$swaps the two outcomes, assigning inflammation to apoptosis and quiescence to necrosis$a18C$ FROM q
UNION ALL SELECT id, 'D', 'adjacent_fact', $a18D$restricts inflammation to pathogen invasion, contradicting that injury of any type triggers it$a18D$ FROM q;

-- Q19 [Cell Migration & Apoptosis | medium | Skill 2 | ans B]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Embryogenesis & Development', $sub19$Cell Migration & Apoptosis$sub19$, $qt19$A vertebrate embryo carries a mutation that abolishes the cell-signaling pathway triggering apoptosis in the web-like tissue spanning its developing fingers and toes, while every other developmental process proceeds normally. An investigator examines the limbs at the end of the embryonic period to predict the resulting anatomical defect.$qt19$, $op19$[{"label": "A", "text": "The digits fail to form at all, leaving smooth paddle-shaped limbs, because apoptosis is what sculpts the bone and tissue of each finger."}, {"label": "B", "text": "The digits fail to fully separate and remain joined by web-like tissue, because the cells normally eliminated between the developing digits were not destroyed."}, {"label": "C", "text": "Extra supernumerary digits grow from the limb, because cells that should have died instead continue dividing into additional fingers."}, {"label": "D", "text": "The limb develops normally with separated digits, because the unneeded interdigital cells are instead cleared by migrating away from the limb."}]$op19$::jsonb, 'B', $ex19$This is a Biology question that falls under the content category 'Mechanisms of Development'. The answer is B because apoptosis normally destroys the cells between the developing digits, and when that programmed death is blocked the interdigital tissue persists and the digits stay joined. The text states that "early stages of development include the formation of web-like tissue between individual fingers and toes" and that "these unneeded cells must be eliminated, enabling fully separated fingers and toes to form. A cell signaling mechanism triggers apoptosis, which destroys the cells between the developing digits" (Bio 11821-11832); the Anatomy text adds that "Paddle-shaped hands and feet develop fingers and toes by the process of apoptosis (programmed cell death), which causes the tissues between the fingers to disintegrate" (A&P 57945). If that apoptosis never occurs, the web-like tissue is not removed, so the fingers remain fused rather than separating. (Choice A) is wrong because apoptosis removes the interdigital cells rather than constructing the digits themselves, so the fingers would still form, not disappear. (Choice B) is correct because failure of the interdigital apoptosis leaves the web-like tissue intact, joining the digits. (Choice C) is wrong because blocking interdigital cell death preserves the existing webbing rather than generating brand-new fingers. (Choice D) is wrong because the text attributes digit separation to apoptosis of the interdigital cells, not to those cells migrating away from the limb. This is a Scientific Reasoning and Problem Solving question because it requires predicting a specific anatomical outcome from the loss of a defined developmental mechanism rather than recalling a stated fact.$ex19$, 'medium', '2C', $cc19$Mechanisms of Development$cc19$, 'biology', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'reversed_relationship', $a19A$Treats apoptosis as constructing the digits rather than removing the tissue between them$a19A$ FROM q
UNION ALL SELECT id, 'C', 'adjacent_fact', $a19C$Substitutes extra-digit growth for retained webbing as the consequence of blocked interdigital death$a19C$ FROM q
UNION ALL SELECT id, 'D', 'process_step_confusion', $a19D$Attributes interdigital clearance to cell migration instead of apoptosis$a19D$ FROM q;

-- Q20 [Cell Migration & Apoptosis | hard | Skill 2 | ans D]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Embryogenesis & Development', $sub20$Cell Migration & Apoptosis$sub20$, $qt20$A researcher applies a drug to a tissue in which cells are undergoing routine apoptosis. Instead of being neatly cleared, the dying cells rupture and spill their contents into the surrounding tissue before phagocytes arrive, and an inflammatory infiltrate soon appears. Which prediction best explains why this treated tissue becomes inflamed when ordinary apoptosis would not have inflamed it?$qt20$, $op20$[{"label": "A", "text": "The drug sped up programmed cell death, and because more rapid apoptosis is intrinsically pro-inflammatory, the accelerated dying directly provokes the infiltrate."}, {"label": "B", "text": "Intact apoptosis already recruits white blood cells to clear the debris, and the drug simply amplified that normal inflammatory clearance signal until an infiltrate became visible."}, {"label": "C", "text": "The ruptured cells lost their attachment to the extracellular matrix, and it is this detachment from the matrix that triggers the immune system to mount the inflammatory response."}, {"label": "D", "text": "The rupture spills the cells' potentially damaging contents into the tissue, so the death now resembles necrosis rather than contained apoptosis and provokes the inflammation that intact apoptosis would have avoided."}]$op20$::jsonb, 'D', $ex20$This is a Biology question that falls under the content category 'Mechanisms of Development'. The answer is D because the inflammation arises from loss of membrane containment, not from the death program itself. Apoptosis normally "allows a cell to die in a controlled manner that prevents the release of potentially damaging molecules from inside the cell," so an intact apoptotic cell never spills its contents and never inflames the tissue. When the drug ruptures the dying cells before phagocytes can engulf them, those damaging molecules flood the surrounding tissue, making the event functionally resemble necrosis. Because "necrosis, or accidental cell death, causes inflammation" while "apoptosis does not initiate the inflammatory response," the spilled contents convert a silent, contained death into a necrosis-like, inflammatory one. (Choice A) is wrong because inflammation here is driven by lost containment, not by the speed of the program; apoptosis does not initiate the inflammatory response no matter how fast it runs. (Choice B) is a tempting partial truth, since phagocytes do clear apoptotic bodies, but normal apoptosis is non-inflammatory, so the infiltrate is abnormal and stems from membrane rupture rather than amplified routine clearance. (Choice C) misassigns the consequence of matrix detachment, which causes a cell to undergo apoptosis as a survival check, not to trigger an inflammatory immune response. (Choice D) correctly chains the loss of membrane integrity to the release of damaging contents, the resulting necrosis-like death, and the inflammation that contained apoptosis would have prevented. This is a Scientific Reasoning and Problem Solving question because it requires the test-taker to trace a multi-step causal chain from an experimental perturbation (membrane rupture) through the released-contents mechanism to a predicted physiological outcome (necrosis-like inflammation), rather than recalling a single fact.$ex20$, 'hard', '2C', $cc20$Mechanisms of Development$cc20$, 'biology', 2, 160
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a20A$Attributing the inflammation to the speed of programmed cell death rather than to loss of containment of cell contents$a20A$ FROM q
UNION ALL SELECT id, 'B', 'partial_truth', $a20B$Correct that phagocytes clear apoptotic debris, but wrongly framing normal apoptosis as inflammatory clearance that the drug merely amplified$a20B$ FROM q
UNION ALL SELECT id, 'C', 'process_step_confusion', $a20C$Confusing matrix detachment as a trigger of the inflammatory immune response when it actually triggers apoptosis as a survival check$a20C$ FROM q;

-- Q21 [Regeneration & Senescence | easy | Skill 1 | ans A]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Embryogenesis & Development', $sub21$Regeneration & Senescence$sub21$, $qt21$A cell biologist tracks a population of human fibroblasts that lack telomerase activity through many rounds of mitosis and observes that the telomeres at the chromosome ends grow progressively shorter with each division. What feature of DNA replication accounts for this gradual shortening?$qt21$, $op21$[{"label": "A", "text": "DNA polymerase synthesizes only in the 5' to 3' direction, and the RNA primer at the 5' end of the lagging strand cannot be replaced, leaving the chromosome ends unpaired."}, {"label": "B", "text": "DNA polymerase proofreads the lagging strand and excises the repetitive TTAGGG telomere sequence as a replication error during each cycle."}, {"label": "C", "text": "DNA polymerase cannot complete synthesis of the leading strand all the way to the end of the linear chromosome, leaving that strand unpaired."}, {"label": "D", "text": "Telomerase removes a block of terminal repeats from the chromosome ends during each S phase in order to regulate chromosome length."}]$op21$::jsonb, 'A', $ex21$This is a Biology question that falls under the content category 'Mechanisms of Development'. The answer is A because DNA polymerase can add nucleotides only in the 5' to 3' direction, and when the replication fork reaches the end of the linear chromosome there is no way to replace the primer on the 5' end of the lagging strand. The text states that the DNA at the ends of the chromosome thus remains unpaired, and over time these ends, called telomeres, may get progressively shorter as cells continue to divide. In cells without telomerase to add the repeats back, this loss accumulates with every round of division. (Choice A) Correct: the 5'-to-3'-only synthesis combined with the unreplaceable 5' lagging-strand primer leaves the ends unpaired and progressively shorter. (Choice B) Incorrect: the text describes no proofreading-removal of the TTAGGG repeats; shortening is due to the primer at the 5' end of the lagging strand not being replaced, not excision of a "replication error." (Choice C) Incorrect: this reverses the strands, because the text states that in the leading strand synthesis continues until the end of the chromosome is reached, while it is the lagging strand whose 5' primer cannot be replaced. (Choice D) Incorrect: telomerase adds repeats to the ends of chromosomes to lengthen and maintain them, rather than removing terminal repeats. This is a Knowledge of Scientific Concepts and Principles question because it requires recalling the established mechanism of the end-replication problem as described in the text.$ex21$, 'easy', '2C', $cc21$Mechanisms of Development$cc21$, 'biology', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'misconception', $a21B$invents a proofreading-excision mechanism that removes telomere repeats$a21B$ FROM q
UNION ALL SELECT id, 'C', 'reversed_relationship', $a21C$swaps leading and lagging strands as the cause of unpaired ends$a21C$ FROM q
UNION ALL SELECT id, 'D', 'misconception', $a21D$reverses telomerase function, claiming it removes rather than adds repeats$a21D$ FROM q;

-- Q22 [Regeneration & Senescence | medium | Skill 2 | ans B]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Embryogenesis & Development', $sub22$Regeneration & Senescence$sub22$, $qt22$A patient suffers a myocardial infarction that kills a localized region of cardiac muscle. A physiologist predicts how that region will be repaired and how the prediction affects the heart's pumping ability. Which outcome is the physiologist most likely to predict?$qt22$, $op22$[{"label": "A", "text": "Satellite cells regenerate the lost cardiac fibers completely, restoring normal contractile function within the original tissue pattern."}, {"label": "B", "text": "Non-contractile scar tissue replaces the dead cardiac muscle, so the region loses contractile power and the heart's ability to pump declines."}, {"label": "C", "text": "Pericytes rapidly replace the dead cardiac cells with new contractile myocytes because cardiac muscle regenerates more readily than smooth muscle."}, {"label": "D", "text": "Resident adult stem cells replace the dead cells with identical cardiac tissue, the same way epithelial tissue replaces lost cells."}]$op22$::jsonb, 'B', $ex22$This is a Biology question that falls under the content category 'Mechanisms of Development'. The answer is B because cardiac muscle does not regenerate to a great extent, so the dead region is repaired by incomplete regeneration: scar tissue, which cannot contract, replaces the lost myocardium. The text states that "Dead cardiac muscle tissue is replaced by scar tissue, which cannot contract. As scar tissue accumulates, the heart loses its ability to pump because of the loss of contractile power." Because the replacement tissue is non-identical and non-contractile, the injured region cannot generate force, and overall pump function declines. (Choice A) is incorrect because satellite cells repair skeletal muscle, not cardiac muscle, and even there they regenerate fibers only "to a very limited extent." (Choice B) is correct because incomplete regeneration of cardiac muscle yields fibrotic scar rather than new contractile fibers, reducing contractile power. (Choice C) is incorrect because pericytes give smooth muscle its readier regeneration, whereas cardiac muscle does not regenerate readily, reversing the true relationship. (Choice D) is incorrect because although epithelial and connective tissues do replace lost cells from adult stem cells, cardiac muscle undergoes only minor regeneration and its dead tissue is replaced by scar. This is a Scientific Reasoning and Problem Solving question because it requires applying the principle of incomplete tissue regeneration to a specific injury scenario and predicting the functional consequence for cardiac output.$ex22$, 'medium', '2C', $cc22$Mechanisms of Development$cc22$, 'biology', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'adjacent_fact', $a22A$Attributing skeletal-muscle satellite-cell repair to cardiac muscle$a22A$ FROM q
UNION ALL SELECT id, 'C', 'reversed_relationship', $a22C$Swapping which muscle type (cardiac vs smooth) regenerates more readily via pericytes$a22C$ FROM q
UNION ALL SELECT id, 'D', 'partial_truth', $a22D$Correct adult-stem-cell replacement for epithelium overextended to cardiac muscle$a22D$ FROM q;

-- Q23 [Regeneration & Senescence | medium | Skill 2 | ans C]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Embryogenesis & Development', $sub23$Regeneration & Senescence$sub23$, $qt23$A research team tracks telomere length in four human cell types over many rounds of division in culture. They predict that one of these cell types will keep its chromosome ends from progressively shortening. Which cell is most likely to maintain its telomere length across repeated divisions?$qt23$, $op23$[{"label": "A", "text": "A mature skin fibroblast, because differentiated somatic cells switch on telomerase once they reach full maturity"}, {"label": "B", "text": "A terminally differentiated skeletal-muscle fiber, because fully specialized cells continuously express telomerase to resist aging"}, {"label": "C", "text": "An adult bone-marrow hematopoietic stem cell, because telomerase is typically active in adult stem cells and rebuilds the chromosome ends"}, {"label": "D", "text": "A circulating mature red blood cell, because telomerase activity rises as a cell becomes more specialized"}]$op23$::jsonb, 'C', $ex23$This is a Biology question that falls under the content category 'Mechanisms of Development'. The answer is C because telomerase, the enzyme that adds repetitive sequences to chromosome ends, is typically active in germ cells and adult stem cells but not in adult somatic cells. An adult bone-marrow hematopoietic stem cell is an adult stem cell, so it expresses active telomerase that rebuilds the telomeres after each division, allowing it to maintain telomere length across many divisions. The text states that "Telomerase is typically active in germ cells and adult stem cells. It is not active in adult somatic cells," and that "Cells that undergo cell division continue to have their telomeres shortened because most somatic cells do not make telomerase," so any somatic cell would instead lose telomere length over repeated divisions. (Choice A) A mature skin fibroblast is a differentiated adult somatic cell; somatic cells do not switch on telomerase at maturity, so its telomeres shorten rather than being maintained. (Choice B) A terminally differentiated skeletal-muscle fiber is also a somatic cell that does not make telomerase, so it does not continuously express the enzyme and cannot rebuild its ends. (Choice C) An adult bone-marrow hematopoietic stem cell is correct because adult stem cells are one of the cell types in which telomerase is normally active, maintaining telomere length across divisions. (Choice D) A circulating mature red blood cell reverses the actual relationship; telomerase activity is associated with germ cells and adult stem cells, not with increasing specialization. This is a Scientific Reasoning and Problem Solving question because the student must apply the rule about which cell types express active telomerase to predict the outcome of an experiment tracking telomere length, rather than simply recalling the enzyme's function.$ex23$, 'medium', '2C', $cc23$Mechanisms of Development$cc23$, 'biology', 2, 105
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a23A$Belief that differentiated somatic cells activate telomerase upon reaching maturity$a23A$ FROM q
UNION ALL SELECT id, 'B', 'process_step_confusion', $a23B$Confusing terminal differentiation with continuous telomerase expression in somatic cells$a23B$ FROM q
UNION ALL SELECT id, 'D', 'reversed_relationship', $a23D$Reversing the association so telomerase activity rises with specialization rather than with germ/stem cell identity$a23D$ FROM q;

-- Q24 [Regeneration & Senescence | hard | Skill 2 | ans D]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Embryogenesis & Development', $sub24$Regeneration & Senescence$sub24$, $qt24$A tumor biopsy reveals cells whose telomeres are markedly shorter than those of the patient's healthy somatic cells, yet these tumor cells continue to divide without limit. An oncologist proposes that disrupting a single enzyme in these cells could halt their proliferation. Which explanation best accounts for the cells' unlimited division and identifies the enzyme to target?$qt24$, $op24$[{"label": "A", "text": "The cells divide indefinitely because their telomeres remain unusually long and have not yet eroded to a critical length, so no end-maintenance enzyme is required."}, {"label": "B", "text": "The cells divide indefinitely because they permanently silence telomerase, removing a brake that would otherwise force them to stop dividing."}, {"label": "C", "text": "The cells divide indefinitely because telomerase, acting as an RNA-dependent RNA polymerase, copies a DNA template into new telomere repeats."}, {"label": "D", "text": "The cells divide indefinitely because telomerase, reactivated after the telomeres shortened, rebuilds the chromosome ends, so inhibiting it could stop their division."}]$op24$::jsonb, 'D', $ex24$This is a Biology question that falls under the content category 'Mechanisms of Development'. The answer is D because the text states that cancerous cells have considerably shortened telomeres and that telomerase becomes active only after that shortening, rebuilding the chromosome ends so the cells escape the replicative limit that would otherwise halt division. Because most somatic cells do not make telomerase, their telomeres shorten with each division and progressively erode, linking telomere attrition to replicative senescence; the cancer cell's reactivation of telomerase reverses this attrition and confers unlimited division. The text adds that if telomerase action in these cells can be inhibited by drugs during cancer therapy, the cancerous cells could potentially be stopped from further division, which is exactly the enzyme the oncologist should target. (Choice A) is wrong because cancer cells have considerably shortened, not unusually long, telomeres, and the scenario explicitly describes markedly shortened telomeres that still allow division. (Choice B) is wrong because telomerase is active, not silenced, in cancer cells, and it enables rather than brakes continued division. (Choice C) is wrong because telomerase uses its built-in RNA template to direct addition of DNA nucleotides, making it a reverse-transcriptase-type enzyme that performs RNA-templated DNA synthesis, not RNA-dependent RNA synthesis. (Choice D) is correct because telomerase reactivated after telomere shortening rebuilds the ends and removes the replicative limit, so inhibiting it is the rational therapeutic target. This is a Scientific Reasoning and Problem Solving question because it requires chaining the senescence-by-attrition concept with telomerase reactivation to predict both the mechanism of immortality and the correct drug target from a clinical scenario.$ex24$, 'hard', '2C', $cc24$Mechanisms of Development$cc24$, 'biology', 2, 160
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'partial_truth', $a24A$Correctly invokes the telomere-length-as-replicative-clock idea but reverses the direction of length change (claims long, unshortened telomeres) so no enzyme is needed.$a24A$ FROM q
UNION ALL SELECT id, 'B', 'reversed_relationship', $a24B$Inverts the role of telomerase, casting it as a silenced brake rather than the active, division-enabling enzyme.$a24B$ FROM q
UNION ALL SELECT id, 'C', 'process_step_confusion', $a24C$Confuses telomerase's mechanism, labeling it RNA-dependent RNA polymerase instead of the RNA-templated DNA synthesis (reverse-transcriptase-type) it actually performs.$a24C$ FROM q;

-- Q25 [Regeneration & Senescence | hard | Skill 2 | ans A]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Embryogenesis & Development', $sub25$Regeneration & Senescence$sub25$, $qt25$A research team works with telomerase-deficient mice that show tissue atrophy, stem-cell depletion, and impaired responses to tissue injury. When the team reactivates telomerase in these adult mice, the atrophy lessens, stem-cell populations recover, and injured tissues such as the intestines once again repair effectively. Which mechanism best accounts for this reversal of the aging-like phenotype?$qt25$, $op25$[{"label": "A", "text": "Reactivated telomerase extends the shortened telomeres, restoring the cells' capacity to keep dividing and thereby regenerate the atrophied, stem-cell-depleted tissues."}, {"label": "B", "text": "Reactivated telomerase triggers apoptosis that clears the senescent, atrophied cells, allowing healthy tissue to fill in the spaces they leave behind."}, {"label": "C", "text": "Reactivated telomerase repairs the rigid cell membranes so oxygen and nutrient transport recovers, independent of any change in telomere length."}, {"label": "D", "text": "Reactivated telomerase lengthens the telomeres so cells permanently stop dividing and enter a protective resting state, ending the atrophy."}]$op25$::jsonb, 'A', $ex25$This is a Biology question that falls under the content category 'Mechanisms of Development'. The answer is A because the textbook attributes the reversal specifically to telomere extension that restores the cells' ability to divide and regenerate. Telomeres are chromosomal regions necessary for cell division, and they shorten each time a cell divides; as they shorten, cells become less able to divide and regenerate, which underlies the atrophy and stem-cell depletion seen in the telomerase-deficient mice. In the 2010 mouse studies, telomerase reactivation caused extension of telomeres, reduced DNA damage, reversed neurodegeneration, and improved the function of the testes, spleen, and intestines—linking the recovery directly to renewed divisive and regenerative capacity rather than to cell death or membrane repair. (Choice A) is correct because extending the shortened telomeres restores the divisive/regenerative capacity that the depleted, atrophied tissues had lost. (Choice B) is wrong because the text credits the reversal to telomere extension restoring division and regeneration, not to programmed cell death clearing senescent cells. (Choice C) is wrong because reduced membrane transport of oxygen and nutrients is a separate cellular aging change, and the reversal described here is tied to telomere extension and reduced DNA damage, not membrane repair. (Choice D) is wrong because shortened telomeres make cells less able to divide, so restoring telomere length restores division rather than permanently halting it. This is a Scientific Reasoning and Problem Solving question because it requires interpreting an experimental phenotype and reasoning backward from the observed reversal to the underlying mechanism that telomere extension restores divisive and regenerative capacity.$ex25$, 'hard', '2C', $cc25$Mechanisms of Development$cc25$, 'biology', 2, 160
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'misconception', $a25B$Attributing the reversal to apoptotic clearance of senescent cells rather than to telomere extension restoring division$a25B$ FROM q
UNION ALL SELECT id, 'C', 'adjacent_fact', $a25C$Substituting a real but separate aging change (membrane transport decline) for the telomere-length mechanism actually responsible$a25C$ FROM q
UNION ALL SELECT id, 'D', 'reversed_relationship', $a25D$Reversing the telomere-length/division relationship so that lengthening telomeres halts rather than restores division$a25D$ FROM q;

